function accountCandidateSelection(form){return JSON.stringify({project:$('[name="opportunity_id"]',form)?.value||'',contact:$('[name="contact_id"]',form)?.value||''});}
function accountCandidateSubmitState(form){const rejecting=$('[name="decision"]',form)?.value==='reject',ready=rejecting||form.dataset.previewReady==='true';for(const button of $$('[type="submit"]',form))button.disabled=form.dataset.accountSubmitting==='true'||!ready;}
function accountSyncCandidateDecision(form){if(!form)return;const rejecting=$('[name="decision"]',form)?.value==='reject';for(const field of $$('[name="value"],[name="opportunity_id"],[name="contact_id"]',form)){field.required=!rejecting;}accountCandidateSubmitState(form);}
async function accountPreviewCandidate(form){if(!form||form.dataset.scope==='stakeholder')return;const generation=Number(form.dataset.previewGeneration||0)+1;form.dataset.previewGeneration=String(generation);form.dataset.previewReady='false';accountCandidateSubmitState(form);const output=$('.account-scope-preview',form),project=$('[name="opportunity_id"]',form)?.value,contact=$('[name="contact_id"]',form)?.value,selection=accountCandidateSelection(form);if((form.dataset.scope==='project'&&!project)||(form.dataset.scope==='contact'&&!contact)){if(output)output.textContent='请选择具体归属，秘书会展示该范围已存资料供你对照。';return;}if(output)output.textContent='正在核对这个范围的已有资料…';const params=new URLSearchParams();if(project)params.set('opportunity_id',project);if(contact)params.set('contact_id',contact);try{const result=await api(`/api/profile-suggestions/${Number(form.dataset.id)}${params.size?'?'+params:''}`);if(form.isConnected===false||form.closest?.('dialog')?.open===false||Number(form.dataset.previewGeneration)!==generation||accountCandidateSelection(form)!==selection)return;const candidate=result.candidate;if(candidate.status!=='pending')throw new Error('候选来源已变化，请重新打开后核对，当前输入仍保留。');form.dataset.currentFactId=candidate.current_fact_id===null||candidate.current_fact_id===undefined?'':String(candidate.current_fact_id);form.dataset.previewSelection=selection;form.dataset.previewReady='true';if(output)output.innerHTML=candidate.current_value?`<p class="analysis-warning">这个范围已存：${e(candidate.current_value.value)} · ${candidate.current_value.basis==='observation'?'观察':'明确信息'}。请对照本次原话，确认后保留旧值历史。</p>`:'<p class="form-hint">这个范围尚无此字段资料，确认后只写入所选范围。</p>';accountCandidateSubmitState(form);}catch(error){if(form.isConnected===false||Number(form.dataset.previewGeneration)!==generation)return;if(output)output.textContent=error.message||'旧值暂时无法核对，请重新选择范围重试；当前输入仍保留。';accountCandidateSubmitState(form);}}
async function accountOpenSettings(customerId,origin){const context=await loadAccountContext(customerId);if(!accountActiveAction(origin))return;const status=context.knowledge?.status;if(!status)throw new Error('自动整理设置暂时不可用，请重新打开客户后重试。');const name=context.network?.unit?.name||state.customers?.find(item=>Number(item.id)===Number(customerId))?.name||'单位全名暂时无法读取，请先核对客户基本资料';openDialog('edit',dialogHeader('自动整理与官方资料','交流自动整理开关对整个工作空间生效；官方域名只属于此单位。','edit')+`<div class="dialog-body"><form id="account-profile-settings-form" ${accountFormMeta(customerId,customerId)}><p>当前单位全名：<strong>${e(name)}</strong></p><button type="button" class="button small" data-edit-customer="${Number(customerId)}">修改单位全名 / 基本资料</button><p class="form-hint">请对照官方主体核对名称；修改后按客户基本资料的流程保存。</p><label class="source-time-confirm"><input type="checkbox" name="enabled" ${status.enabled?'checked':''}> 持续从新交流提出画像候选（全工作空间）</label><label class="source-time-confirm"><input type="checkbox" name="auto_research" ${status.auto_research?'checked':''}> 允许自动探索公开资料（全工作空间）</label><p class="form-hint">${status.research_configured?'公开检索已配置，仍需核对单位身份与时效。':'公开检索尚未配置；开启后也不会凭空生成公开信息，可先粘贴资料。'}</p><label for="account-domains">你已核对的此单位官方域名</label><textarea id="account-domains" name="official_domains" rows="3" placeholder="example.com，每行一个域名，最多10个">${e((status.customer_settings?.official_domains||[]).join('\n'))}</textarea><p class="form-hint">只填写你已核实的官方域名。候选里发现的网站不能自己证明自己。开启不会重扫全部旧记录，可单独使用“整理已有交流”。</p>${accountFormFooter('保存整理设置')}</form></div>`);}
function accountOpenImport(customerId){openDialog('edit',dialogHeader('从公开资料补充观察','贴一个公开链接让秘书读取，或粘贴原文；核对后再提出候选。','edit')+`<div class="dialog-body"><form id="account-public-source-form" ${accountFormMeta(customerId,customerId)}><label for="account-public-url">原文地址 *</label><input id="account-public-url" name="url" type="url" required placeholder="https://..."><button type="button" class="button small" data-public-page-preview>读取链接正文</button><p class="form-hint">只读取公开文字页面；无需配置搜索API。读取后先核对正文，再保存候选。</p><label for="account-public-title">标题 *</label><input id="account-public-title" name="title" required maxlength="500"><label for="account-public-entity">原文对应单位全名 *</label><input id="account-public-entity" name="entity_name" required maxlength="120" value="${e(accountContextCache.get(Number(customerId))?.network?.unit?.name||state.customers.find(item=>Number(item.id)===Number(customerId))?.name||'')}"><label for="account-public-date">发布日期（未知留空）</label><input id="account-public-date" name="published_at" type="date"><label for="account-public-text">公开原文 *</label><textarea id="account-public-text" name="text" rows="7" required maxlength="20000"></textarea><p class="form-hint">请保留年份、否定和条件。全名命中也可能是同名单位，之后仍需确认身份；资料始终作为公开观察。</p>${accountFormFooter('保存原文并提取候选')}</form></div>`);}
async function accountDiscussQuestion(customerId,projectId,question){
  const body={customer_id:customerId,opportunity_id:projectId,source_record_id:null,request_id:newVisitRequestKey()};
  if(question?.scope==='contact'){
    if(!accountContactDiscoveryFields.has(question.field_key)||!Number.isSafeInteger(Number(question.contact_id))||Number(question.contact_id)<=0||!Number.isSafeInteger(Number(projectId))||Number(projectId)<=0||Number(question.opportunity_id)!==Number(projectId))throw new Error('联系人探索提示归属已有变化，请重新打开当前项目后核对。');
    body.contact_id=Number(question.contact_id);
  }
  const opening=openDiscussionContext({...body,...(body.contact_id?{contact_name:question.contact_name||question.name||'',contact_department:question.contact_department||question.department||'',timeline_enabled:true}:{})}),generation=Number(state.discussionLoadGeneration||0),navigationRequest=state.request;
  await opening;
  if(state.view!=='discussions'||Number(state.discussionLoadGeneration||0)!==generation||state.request!==navigationRequest)return;
  const result=await api('/api/sales-discussions',{method:'POST',body});
  if(state.view!=='discussions'||Number(state.discussionLoadGeneration||0)!==generation||state.request!==navigationRequest){notify('探索问题的讨论已保留在历史列表，可稍后继续。');return;}
  const threadId=Number(result.thread?.id||result.id),threadOpening=openDiscussionThread(threadId),threadGeneration=Number(state.discussionLoadGeneration||0);
  await threadOpening;
  if(state.view!=='discussions'||Number(state.discussionLoadGeneration||0)!==threadGeneration||Number(state.discussion?.thread?.id)!==threadId)return;
  const field=$('#discussion-message-form [name="text"]');
  if(question&&field&&!field.value.trim()){field.value=`${question.scope==='contact'?`关于${accountContactLabel(question)}在「${question.project_name||'本项目'}」中的沟通与推进，`:''}围绕「${question.label}」，我下一步应该如何提问和推进？\n${question.ask}`;field.dispatchEvent(new Event('input',{bubbles:true}));field.focus();}
  notify(`已带入${projectId?'本项目':'本单位'}和探索问题；补充情况后发送，采纳建议再形成待办。`);
}
