  if(form.id==='account-profile-settings-form'){const domains=String(values.official_domains||'').split(/[\s,，;；]+/).filter(Boolean);await api(`/api/customers/${customerId}/profile-intelligence/settings`,{method:'PATCH',body:{enabled:Boolean(values.enabled),auto_research:Boolean(values.auto_research),official_domains:domains}});message='自动整理设置已保存';}
